import copy

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def _setattrs(self, items):
        for key, value in items:
            setattr(self, key, value)

def create_point(x, y):
    return Point(x, y)

def replace_point(pt, **changes):
    return pt.evolve(**changes)
